) AS (
  VALUES 
    (233::BIGINT, 'Nunca suelo opinar en Mis Profesores, pero es el peor profesor que he tenido en varios años de estar en el tec, es vago, mediocre, todo el curso se resumen en "segun el X libro", tenes una consulta: "revise el libro tal", califica suave, pero cada evaluacion es dificil, sino es repitente, no lo llev'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-10-22T00:00:00+00:00'::TIMESTAMPTZ, '5b43d407c28c04fc3de6479a5b46c5b78192a0a4f609fec0b33f6c0e738d1567'::TEXT, ARRAY[933]::BIGINT[]),
    (233::BIGINT, 'Pierdanse la oportunidad de cualquier curso con el,repito,pierdansela,va rapidisimo,no explica nada,solo resuelve como si uno ya tuviera las bases,y lo considero muy prepotente,el peor profe que me ha tocado'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2026-03-19T00:00:00+00:00'::TIMESTAMPTZ, 'd7bf8df9ee27752260826a72d643e1fdd9ab41f15af476e4d936f7fb1ab3dd2a'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'El profesor es buena persona, da puntos extras y no califica tan duro. Sin embargo, no explica bien y las clases son muy cansadas y largas. Nos motiva a ir a consulta, pero las 2 veces que fuí le urgía ir a tomar "café" estando en su horario consulta. Es muy desordenado. Da puntos extra por asistir.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-01-10T00:00:00+00:00'::TIMESTAMPTZ, '71955c58490bd11a9feff0263f91f31d4e7c5d4bea8c80b59ca8f092db646f4b'::TEXT, ARRAY[933]::BIGINT[]),
    (233::BIGINT, 'Realmente no es tan mala opción, da bastantes puntos extra y no califica realmente duro, el curso en sí es bastante pesado y con muchos trabajos, lo recomendable es tener buen grupo trabajo, es cierto que no explica muy bien (Descriptiva principalmente) pero con los videos de la cátedra se la juega.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2025-12-13T00:00:00+00:00'::TIMESTAMPTZ, '0a143571b15585c41f956b6c212c04e8410d1f051e2e9e1d17d603d2464bda3f'::TEXT, ARRAY[933]::BIGINT[]),
    (233::BIGINT, 'maes, POR FAVOR salvense de este profe. en las clases va rapidisimo y no explica nada solo resuelve. califica durísimo, es un dolor para sacar consulta, y tras de que el curso es difícil el mae no ayuda casi nada, por más que uno se esfuerce este curso es casi que autodidacta. de verdad ni lo piense'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'bf0b234ffc41320a8f7cdaa5d3374faa9767a7ac140562081cbdb6fe426c1c4c'::TEXT, ARRAY[933]::BIGINT[]),
    (233::BIGINT, 'enserio que para los que vean esto, de corazon les digo, NO MATRICULEN NI UN SOLO CURSO CON ESTE PROFE, es que de verdad ni lo piensen, el curso aparte de ser duro, con este profe es casi que imposible, por mas esfuerzo y dedicacion. SIMPLEMENTE ESTE PROFE NO AYUDA EN NADA, POR FAVOR CON EL NO'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2025-11-22T00:00:00+00:00'::TIMESTAMPTZ, '0b5f020434484ed42b20c629f1884d4e27e102f8855a13805c1ccfa7fc7696aa'::TEXT, ARRAY[933]::BIGINT[]),
    (233::BIGINT, 'No se puede seguir el ritmo de la clase, es imposible entenderle. Tenía un expectativa mala del man pero este semestre superó lo que pensaba (en el mal sentido)'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-10-30T00:00:00+00:00'::TIMESTAMPTZ, '8858324c0716310b6b19f3ea54febb17104a9b98ab7e8925b68ed31db900ce29'::TEXT, ARRAY[933]::BIGINT[]),
    (233::BIGINT, 'Debido a que no va con la cátedra cambia el formato de las tareas, esto sería muy útil si explicara bien. Solo renta llevar el curso con él si se está repitiendo y ya domina la materia, ya que si se le pregunta algo responde de forma grosera y despectiva. No empatiza con los estudiantes y no ayuda.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2025-08-11T00:00:00+00:00'::TIMESTAMPTZ, 'a182bdcf0cc425687d10c11ed4df11f3612d4934a3db6b620c82fc088918c0e0'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Tenía miedo de matricular este curso con él, sin embargo se mostró muy diferente a lo que he escuchado y a lo que dicen por acá, brinda ayuda desde el inicio, es un poco ortodoxo pero nada que uno no pueda manejar. Explicó todas las veces necesarias para que todos entendiéramos.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'bbd7c1bbcbef1371545b71a2c7206826cbc03c24ccba9e9caf4529a72df3723f'::TEXT, ARRAY[933]::BIGINT[]),
    (233::BIGINT, 'Es malísimo explicando, imposible seguirle el ritmo, responde de mala gana, es inconsistente con sus evaluaciones, las evaluaciones en general son un desorden (no va con la cátedra), califica demasiado duro sin explicar por qué, se enoja si se le reclama algo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2025-06-26T00:00:00+00:00'::TIMESTAMPTZ, '763a93500da7a5a9828d50ee9c98ebe941b7cc7ad53533ca56611c997d09f6ff'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Geometria no explica bien pero conjuntos mec y planos el mae es un dios, se aprende más que otros profes en estos temas que para mante es bastante importante. El mae es gracioso y es un roco es complejo de tratar pero simplmente pongale bstantw y vaya a consulta para que lo recozca'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2025-06-16T00:00:00+00:00'::TIMESTAMPTZ, '7c3994783d7d30ebbf3d5affbfe334c7b6ecb32146964d4f0a8f4b9542853645'::TEXT, ARRAY[933]::BIGINT[]),
    (233::BIGINT, 'Va demasiado rápido, no explica con claridad. Si llevan con él no esperen seguir el ritmo, o solo se puede escuchar lo que dice o hacer la práctica. Se debería ir haciendo las dos cosas para entender. Además las tareas ni si quiera son las mismas de la cátedra.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2025-03-17T00:00:00+00:00'::TIMESTAMPTZ, '03feb62fb2160360cad9e83ec63e64657ab313d16fd3073373c755779ea4d4e6'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'El peor profe con el que me he cruzado con diferencia. Es cero profesional, no sabe explicar, hace comentarios burlistas y fuera de lugar. En ocasiones llega de mal humor y se desquita con los estudiantes. No responde ni correos ni mensajes. Califica muy duro y sin sentido.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2024-12-30T00:00:00+00:00'::TIMESTAMPTZ, '326af768f88312b5177a72c4ad43a0495e2e1c855c42bf0423f79c5eca926d29'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Es casi imposible pasar incluso sabiendo del curso, está separado de la cátedra entonces todo lo hace diferente y más difícil. Los exámenes son fáciles pero pide muchos entregarles, por lo que es poco tiempo. El asistente califica las tareas muy duro. Muy necio con asistencia. Buena gente.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'bc8072397202f2de427b3c2c6446f233aa0bf3bf0c5d04078bfc9fe3c64a9560'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'GENTE EVITENLO POR FAVOOOOR. No meta con él ni aunque usted sepa de dibujo, es pésimo explicando, las tareas larguísimas y revisa super mal, supuestamente sabe mucho pero no sabe enseñar asi que de nada sirve si no sabe transmitir el conocimiento.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'f379233bb6fa60d04b53aa5554f6ffa401a30d7d02dddae6ce82d2bbcccd75cb'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Si usted piensa matricular algo con él, vale la pena atrasarse un semestre antes de llevar con este profesor, aunque sea el ultimo que quede por la hora de matricula. No sabe usar solidworks, explica pésimo, califica como si explicara bien, no hay espacio aqui para explicar lo mal profesor que es'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-11-12T00:00:00+00:00'::TIMESTAMPTZ, '6906b19fd21b1cb01694e985cda733f266375a605aa1f4bcb606b14786624e8a'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'No sabe explicar para nada, se pasaba media clase hablando de como se fue a la unión soviética a estudiar y otras cosas totalmente innecesarias, aparte de que si no adquiere el ridículo libro que él mismo escribió se hace difícil pasar la clase. Usa sus propias tareas y no las de cátedra.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '7d7b99091f1bcedb9a17667747396f9da7e402f00a695372d508c91e6bcb23e1'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Él sabe muchísimo pero no sabe explicar. Deja tareas muy largas y distintas a lo de la cátedra. Va a un ritmo muy rápido y sí ud no sabe se queda perdido. Sí ya sabe algo de dibujo técnico se le facilita sino no. Da puntos extra y es amable y reza.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'ecc5ff5880eaf4a993feabbde9e3c47fb97462f3df7b243e584cbca61ffba19c'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'El profesor es bueno como persona, trata de ayudar lo más que pueda, pero no es bueno explicando. Si está en verano es recomendable, ya que las evaluaciones dependen solo de él, además de que brinda apoyo en consulta si muestra interés, pero durante semestre normal, evítelo si no conoce la materia.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Muchos proyectos grupales']::TEXT[], '2024-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'b39b6eb8a2ad4c172606aee8526f8cdbe5c6924bb872c04eb1eead2cfb67ac19'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Si es la primera vez que lleva el curso no matricule con este profe, no sabe explicar además que lo obliga a uno a comprar un libro hecho por el que no se usa nada, además que supuestamente las clases son 100% presenciales pero el profe decide el mismo día si la hace virtual o no'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2023-11-07T00:00:00+00:00'::TIMESTAMPTZ, '141a0a8546b51e5a58821eb5c4dfbe73803a607d2562211e25be33f8cb6fb2a9'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Se nota que sabe de lo que habla, pero no sabe enseñar, es un pésimo profesor. No matricule con él. Cualquier curso con él es muy difícil de pasar.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2023-10-14T00:00:00+00:00'::TIMESTAMPTZ, '3b04bc9f3a3c4ea0e2243703402df6052af96a9c737b6d9a13699816dd393581'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'DE VERDAD QUE ESTE PROFE NOOOOO, META CON EL DE ULTIMA OPCION, ES REALMENTE MALO, YO PASÉ PRACTICAMENTE IENDO VIDEOS DE YT, EXPLICA TERRIBLE Y HACE LOS EXAMANES LO MÁS DIFÍCIL POSIBLE'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '7d918e7b85cc7e9e13f8f7c42938e953981fcce2ee20df05a2c4bc6052d4885b'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'MAES NO MATRICULEN CON ESTE PROFE. Con todo el respeto que se le puede tener es malísimo, no se le entiende nada, no quiere explicar, manda tareas larguísimas y tras de todo califica re mal y no le gustan reclamos. Da puntos dudosos a güilas por favores raros así que si es un mae de el curso perdido'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '586fe6d3f285efdeedb7dad79aa89a6e21643bc4c935ce9a836abe26711ae2a7'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Digamos que el profe como tal es buena gente, el detalle es que casi todos los trabajos grandes del curso son en grupo. La primera parte del curso es pura geometría descriptiva y la segunda es solidworks, en esta parte nosotros casi que dabamos la clase como "proyecto". Hay que ponerle para pasar.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'c242a4d83e8b89498bfe7184a1164f02a0a912a030599ac4169d13e2db8cb1a1'::TEXT, ARRAY[933]::BIGINT[]),
    (233::BIGINT, 'No ayuda en nada, explica haciendo las cosas más difíciles.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '618d75f3fc3a5f66bfcdf43426649a9d6a3bc9f75458f923f8a09e387c877600'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'NO VOLVERÍA A LLEVAR EL CURSO CON EL :/ le sabe a la materia pero no para explicarla , además se enreda mucho con la materia , a veces da la materia por vista y no te explica si tienes dudas'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, '30cc5a7fd0644cb5ad02496b1ef78e0e284c286a84d56e596cce14eeea930660'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'El profesor tiene abundante conocimiento de la materia, sin embargo no sabe dárselo a los estudiantes, califica sin criterios, cuando uno le pide ayuda le dice que eso se vio en la clase por más sencilla que sea la pregunta, da tareas extra que aunque complicadas no son obligatorias.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Exámenes retadores']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '97d482254a6c34cd69c0745030c614b5c6a7ac8e258f4f92084199be56c40ec1'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'El profesor se denota de mucha experiencia en su campo, peropedagógicamente es muy deficiente. Explica temas por encima, no se cerciora de que los estudiantes aprendan, aunque sea presencial da la clase hacia su computadora cómo si fuera virtual. Aún así las maquetas son muy chivas e entretenidas!'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2023-05-19T00:00:00+00:00'::TIMESTAMPTZ, '8b85cd610e4d38321ba7003a3e05b7bef48fe821899540ecd3c2d1f78487aa25'::TEXT, ARRAY[933]::BIGINT[]),
    (233::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2023-05-10T00:00:00+00:00'::TIMESTAMPTZ, '1e6e1abaff5515583c0c9288dfc2d9a68b445990879ee0eab8d367641dca90da'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Es muy purista con las reglas de dibujo, siempre va a querer hacer todo como lo indica la norma por más anticuado o insignificante que sea.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2023-01-31T00:00:00+00:00'::TIMESTAMPTZ, '827e011ac07680e99a504bcf5aac9f286ad0750a5d407645ff0156e2c2b2f674'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Le gusta demasiado hablar sobre él. Para explicar es malisimo, los asistentes siempre son igual de malos que el, califican durisimo. NO lo recomiendo, nunca se le queda bien.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-02T00:00:00+00:00'::TIMESTAMPTZ, '3131229dd9be4e79a4bafbfcbec8181ddc1a3fdba364b699853101c17f919ea1'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Completamente inncesario la dificultad que le da a las cosas faciles. De todas formas, al no estar en la catedra los examenes son bastante más faciles que en los otros grupos.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'af81ffff367feab654cb701762843f2e7c45a3b8830f57584d5ba8fcef41979e'::TEXT, ARRAY[933]::BIGINT[]),
    (233::BIGINT, 'NOOOO MATRICULE CON ÉL!!... Califica super rudo,no explica, es arrogante... Deja demasiada tarea ! Mucha política (literal) !!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2022-02-03T00:00:00+00:00'::TIMESTAMPTZ, '0e87e92035f8c41e924029f67984f13c5d8d9cef928203812fd67e7fe85dcb0a'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Llevo el curso en verano virtual, sabe demasiado, deja muchos videos para clases asincrónicas, da consultas y buena retroalimentación, buen profe.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-12-21T00:00:00+00:00'::TIMESTAMPTZ, '2ac82857e2a60f2b72fd55b35f25a322b1668690c8d2db3c652be504452d3e9e'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'No sabe explicar, deja videos muy largos, es muy desordenado, las clases son muy aburridas. Para nada recomendado.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-10-29T00:00:00+00:00'::TIMESTAMPTZ, '6b1c08166212b53f0e636cd126d72dc22789b18cec1103aa5ad7451c11bf9fd6'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Malísimo, un profesor que como profesional es respetable pero como profesor es una porquería, en virtual almenos deja videos eternos y nunca se esmera porque uno entienda, el curso es rudo y él lo hace 3 veces más rudo los exámenes son muy duros,NO MATRICULE POR NADA DEL MUNDO CON ESTE PROFE.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2021-08-30T00:00:00+00:00'::TIMESTAMPTZ, '0c8206993846ec22d8a91345d1ab00423870aa69bc1e67bce29bc1cd61224e72'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'El profesor no sabe expresarse, da demasiadas vueltas para explicar algo sencillo, es increíblemente desordenado. Sus clases se vuelven tediosas y aburridas. Uno se puede apoyar un poco con el material de la cátedra, el material audiovisual del profe es pésimo. Yo lo sentí bastante vago.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, '1b3e6726369b6265f42ba5939b43300d37f8be7756429bd73d898df72307c6fd'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Se nota que sabe mucho pero no sabe cómo explicarlo de la mejor forma, deja videos para entender la materia. Es importante preguntar bastante y poner atención a los videos. Si se aprende pero hay que ponerle.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'ba0b07a4c92fe96185ed0c35fc678cc21d836ecc8e9e1e5f0c2cd65822381151'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'd42aba30408728796475572ad9ab6dfada1eba25755f1a729635afee7b2cca06'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'El tipo sabe mucho, pero no se sabe expresar y dar a entender, deja videos larguísimos antiguos para explicar cosas que se pueden en menos de 15minutos, sus clases son aburridas, cambia de horario cuando le ronca el cul0, deja trabajos largos, hace grupos para evaluaciones rarísimas.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, '2c9c63e8adf4f631c0ae89784c383f927e3fac363b9c0ee8855e3b2c853bd087'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Es una lástima porque se nota que el profesor se esfuerza porque uno entiende, pero simplemente no es bueno explicando, sus clases asincrónicas son DEMASIADO largas y él no se da a entender. Es un excelente profesional pero no tan buen profe'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '764cfcc4ed313cf4170730266f558a62e56c6f8caecc16d7b08fc86daaf6f5d0'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'El profesor es lo más desordenado que existe, tanto para dar trabajos, y para dar lecciones. Tiene dificultades para expresar lo que sabe, honestamente no parece que le interese que el estudiante aprenda.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'f1f47d95eebb50745d82afc5fdf151edbae679f8257477f1d59cf09103a6a689'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-05-24T00:00:00+00:00'::TIMESTAMPTZ, '2c18e5f599d20865f01e41fee454fabb2e09f950cae6a9d69b9343909f228bc5'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'Mal profesor. Si ha llevado dibujo en algun colegio tecnico se le va a hacer muy facil pero si no mejor lleve con otro. Deja videos largos de una explicacion que se puede hacer en 30 minutos, califica los trabajos muy despues y aburre mucho sus lecciones'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2021-02-15T00:00:00+00:00'::TIMESTAMPTZ, '30e6ae2cb4a41ec0c0378d36ae83bfd6217ad3a458d9ab83d4b9cd557125090f'::TEXT, ARRAY[610]::BIGINT[]),
    (233::BIGINT, 'El Curso es pesado, el proyecto lo maneja diferente, si usted ya llevo el curso llevelo con el porque deja usar los mismos planos, en clases virtuales tiene muy mal internet pero las clases son asincronicas, deja videos y se conecta solo para resolver dudas, ayuda al final poniendo tareas o correcci'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, '977aae649d244e4ce956f1dbc885138b82cf05686710766848f2c93820e14cd6'::TEXT, ARRAY[933]::BIGINT[]),
    (233::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'd5447c6b3483510c71792560971a68011a60eaad22be349c344474473ab71731'::TEXT, ARRAY[933]::BIGINT[]),
    (233::BIGINT, 'El curso ya en pesado, pero el profesor lo vuelve aún más, si usted es de Mante o de verdad quiere aprender llévelo con él, pero si solo quiere pasarlo, busque a otro. SI USTED TIENE ALGÚN TIPO DE ADECUACIÓN, NO LLEVE CON ÉL.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'a9ac2bc8c6a1c48bd3632388cc4a810ed527d7db3e507fc778083689cf797707'::TEXT, ARRAY[610]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
